<script setup>
import {Head, Link, useForm} from '@inertiajs/vue3';
const props=defineProps({activationCode:String});
const form=useForm({name:'',phone:'',email:'',activation_code:props.activationCode||'',password:'',password_confirmation:''});
const submit=()=>form.post(route('membership.register.store'),{onFinish:()=>form.reset('password','password_confirmation')});
</script>
<template><Head title="Activa tu cuponera"/><main class="activation"><section class="brand"><img src="@assets/images/logo-light.png" alt="Hacienda Monterrico"><span>CLUB DE SOCIOS</span><h1>Bienvenido</h1><p>Activa la cuponera de tu familia con el código impreso en la tarjeta.</p></section><form @submit.prevent="submit"><label>Nombre y apellido del titular<input v-model="form.name" autocomplete="name" required><small>{{form.errors.name}}</small></label><div class="grid"><label>Celular<input v-model="form.phone" type="tel" autocomplete="tel" required><small>{{form.errors.phone}}</small></label><label>Correo electrónico<input v-model="form.email" type="email" autocomplete="email" required><small>{{form.errors.email}}</small></label></div><label>Código de activación de la tarjeta<input v-model="form.activation_code" autocomplete="one-time-code" required><small>{{form.errors.activation_code}}</small></label><div class="grid"><label>Contraseña<input v-model="form.password" type="password" autocomplete="new-password" required><small>{{form.errors.password}}</small></label><label>Confirmar contraseña<input v-model="form.password_confirmation" type="password" autocomplete="new-password" required></label></div><button :disabled="form.processing">{{form.processing?'Enviando…':'Enviar código de verificación'}} <i>→</i></button><p class="login">¿Ya tienes una cuenta? <Link :href="route('login')">Inicia sesión</Link></p></form></main></template>
<style scoped>.activation{min-height:100vh;background:linear-gradient(145deg,#2d241e,#58372b);display:grid;place-items:center;padding:32px;color:#332820}.activation>section,.activation>form{width:min(660px,calc(100% - 30px))}.brand{text-align:center;color:#fff8e9}.brand img{max-width:260px;max-height:100px;object-fit:contain}.brand span{display:block;color:#c9b990;letter-spacing:.25em;font-size:10px}.brand h1{font:44px Georgia;margin:18px 0 5px}.brand p{color:#eadfce}.activation form{background:#fffaf1;border-radius:22px;padding:30px;box-shadow:0 22px 60px #160d0988}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{font-size:12px;font-weight:700;display:block;margin:12px 0}input{display:block;width:100%;margin-top:7px;padding:12px;border:1px solid #d9cdbd;border-radius:9px;background:white}small{display:block;color:#993b2a;margin-top:4px}button{width:100%;margin-top:16px;padding:14px;border:0;border-radius:9px;background:#993b2a;color:white;font-weight:800}button i{float:right}.login{text-align:center;font-size:12px;margin:18px 0 0}.login a{color:#993b2a;font-weight:700}@media(max-width:600px){.grid{grid-template-columns:1fr}.activation{padding:20px 0}.activation form{padding:22px}.brand h1{font-size:34px}}</style>
